const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const canberra = ee.Geometry.Point([149.13, -35.28]);
  const startDate = '2020-01-14';
  const endDate = '2020-01-23'; // GEE date range is exclusive of the end date, so use the 23rd.

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
                   .filterBounds(canberra)
                   .filterDate(startDate, endDate);

  const imageCount = chirps.size().getInfo();
  if (imageCount === 0) {
    console.log('No CHIRPS images found for the specified date and location.');
    console.log('A: No'); // No images means zero rainfall.
    return;
  }
  console.log(`Found ${imageCount} daily rainfall images.`);

  // 3. Processing: Calculate total precipitation
  // Sum all daily precipitation images in the collection into a single image.
  const totalPrecipitation = chirps.select('precipitation').sum();

  // 4. Calculation: Extract rainfall value at the point
  // Reduce the region to get the pixel value. The reducer doesn't matter much for a single pixel.
  const scale = 5000; // Native resolution of CHIRPS is approx. 5km.
  const precipDict = totalPrecipitation.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: canberra,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation');

  // getInfo() can return null if the point is outside the image footprint.
  const totalPrecipitation_mm = precipDict.getInfo();

  // 5. Validation & Final Answer
  if (totalPrecipitation_mm === null) {
      console.log('Calculation failed: The location may be outside the data coverage area.');
      console.log('C2: No Valid Pixels');
      return;
  }

  // Convert millimeters to inches (1 inch = 25.4 mm)
  const totalPrecipitation_inches = totalPrecipitation_mm / 25.4;
  const threshold_inches = 8;

  console.log(`Total rainfall from ${startDate} to ${endDate.substring(0, 10)}:`);
  console.log(`Millimeters: ${totalPrecipitation_mm.toFixed(2)}`);
  console.log(`Inches: ${totalPrecipitation_inches.toFixed(2)}`);
  console.log(`Threshold (inches): ${threshold_inches}`);

  if (totalPrecipitation_inches > threshold_inches) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error('An error occurred during initialization or analysis.');
    console.error(e);
    console.log('D');
  }
}

initEE();
